  ('an-oasch-wiara-aunkapfead-haum', 'an Oasch wiara Aunkapfead haum', '', '', '', '', 'einen Arsch wie ein Ankerpferd haben', '[{"kategorie": "wörtlich", "text": "\"ein plumpes, unförmiges Gesäß haben (wie die Zugpferde der Anker-Brotfabrik in Wien)\";   (scherzhaft für):  2. einen Hintern wie ein Elefant haben"}, {"kategorie": "", "text": "einen Arsch wie ein Flugzeugträger haben"}, {"kategorie": "", "text": "einen Hintern wie ein Brauereipferd haben"}, {"kategorie": "", "text": "[[An Oasch wiara Lok haum]]"}, {"kategorie": "", "text": "[[an Oasch wiara Lewakaassemmä um 1.000 Euro haum]]"}]'::jsonb, ''),
  ('aunka-ua', 'Aunka-Ua', '', '', '', '', 'Ankeruhr', '[{"kategorie": "hist.", "text": "Eine der bekanntesten Sehenswürdigkeiten beim Haus der Helvetia-Versicherung am [[Hohen]] Markt im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Ankeruhr ist eine Jugendstil-Uhr, die 1911–1914 von Franz von Matsch entworfen wurde. Die Uhr ist an der Fassade des Gebäudes der ehemaligen Anker-Versicherung angebracht und zeigt 12 bedeutende historische Persönlichkeiten, die im Laufe des Tages in einem mechanischen Uhrwerk vorüberziehen. Um 12:00 Uhr mittags kann man die gesamte Parade der Figuren sehen, begleitet von Musik"}, {"kategorie": "", "text": "Die Ankeruhr gilt als eines der herausragenden Werke des Jugendstils und ist eine beliebte Touristenattraktion"}]'::jsonb, ''),
  ('puenktlich-wia-de-aunka-ua', 'pünktlich wia de Aunka-Ua', '', '', '', '', 'pünktlich wie die Ankeruhr', '[{"kategorie": "wörtlich", "text": "\"pünktlich wie ein Uhrwerk\" (Zur Erklärung: Die [[Ankeruhr]] ist eine Jugendstil-Uhr, die 1911–1914 von Franz von Matsch entworfen wurde. Die Uhr ist an der Fassade des Gebäudes der ehemaligen Anker-Versicherung am [[Hohen]] Markt im 1. Wiener Gemeindebezirk [[[Innere]] Stadt] angebracht und zeigt 12 bedeutende historische Persönlichkeiten, die im Laufe des Tages in einem mechanischen Uhrwerk vorüberziehen. Um 12:00 Uhr mittags kann man die gesamte Parade der Figuren sehen, begleitet von Musik)"}, {"kategorie": "fig.", "text": "pünktlich wie der Gongschlag, sehr pünktlich, überpünktlich"}]'::jsonb, ''),
  ('des-kraeud-mi-au', 'Des kräud mi au!', '', '', '', '', 'Das kräult mich an!', '[{"kategorie": "", "text": "Das regt mich auf!  2. Das macht mich wütend!  3. Das bringt mich auf die Palme!"}]'::jsonb, ''),
